head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > main]<br/>현재 화면이 속한 Window 를 기준으로 최상위 페이지의 Scope 객체를 반환합니다.",
    "validation" : [
        "현재 화면이 속한 Window 를 기준으로 최상위 페이지의 Scope 객체를 반환해야 합니다.",
        "반환된 Scope 객체를 통해 최상위 화면에 구성된 scwin 객체 및 컴포넌트에 접근할 수 있어야 합니다.",
        "현재 화면이 'iframePopup', 'browserPopup' 팝업인 경우 별도의 Window 객체에 생성되므로 팝업의 최상위 페이지 Scope 객체를 반환해야 합니다.",
    ]
}


// 최상위 화면의 scwin 함수 ($p.main() 반환 Scope 를 통해 호출됨)
scwin.getMainPageInfo = function () {
    return "최상위 페이지 scwin.getMainPageInfo() 호출 성공";
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_main_main_onclick = function () {
    var mainScope = $p.main();

    wf_body_bottom.getObj("scwin").setReturnValue("메인 $p.main() 반환 타입 : " + (typeof mainScope));
    wf_body_bottom.getObj("scwin").setReturnValue("메인 $p.main() === window 여부 : " + (mainScope === window));
    wf_body_bottom.getObj("scwin").setReturnValue("메인 $p.main().scwin 존재 여부 : " + (typeof mainScope.scwin !== 'undefined'));
}



scwin.btn_main_wframe_onclick = function () {
    var mainScope = wf_mid.getObj("$p").main();

    // 최상위 화면의 InputBox 에 값 설정
    mainScope.ibx_top.setValue("Example");

    // 최상위 화면의 scwin 함수 호출
    var rtn = mainScope.scwin.getMainPageInfo();

    wf_body_bottom.getObj("scwin").setReturnValue("wf_mid 내부 $p.main() 반환 타입 : " + (typeof mainScope));
    wf_body_bottom.getObj("scwin").setReturnValue("  ibx_top.setValue('Example') 후 getValue() : '" + mainScope.ibx_top.getValue() + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("  scwin.getMainPageInfo() : " + rtn);
}



scwin.btn_openBrowserPopup_onclick = function () {
    var options = {
        id: "main_browserPopup",
        type: "browserPopup",
        width: "500px",
        height: "250px",
        top: "100px",
        left: "100px",
        popupName: "main browserPopup 테스트",
        modal: false
    };

    $p.openPopup("/sample/common_link/$p_main_popup.xml", options);
    wf_body_bottom.getObj("scwin").setReturnValue("openPopup 실행 (browserPopup)");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 $p.main() 결과(팝업 최상위 Scope)를 확인하세요.");
}
